        // Constructors
        constructor(properties?: Partial<Store.ConstructorProps>, ...args: any[]);

        _init(...args: any[]): void;

        // Signals
        /** @signal */
        connect_after<K extends keyof Store.SignalSignatures>(signal: K, callback: GObject.SignalCallback<this, Store.SignalSignatures[K]>): number;
        connect_after(signal: string, callback: (...args: any[]) => any): number;

        /** @signal */
        emit<K extends keyof Store.SignalSignatures>(signal: K, ...args: GObject.GjsParameters<Store.SignalSignatures[K]> extends [any, ...infer Q] ? Q : never): void;
        emit(signal: string, ...args: any[]): void;

        // Virtual methods
        /**
         * Returns if this folder (param info) should be checked for new mail or not.
         * It should not look into sub infos (info->child) or next infos, it should
         * return value only for the actual folder info.
         * Default behavior is that all Inbox folders are intended to be refreshed.
         * @param info a {@link Camel.FolderInfo}
         * @since 2.22
         * @virtual
         */
